create extension if not exists pgcrypto;
do $$ begin create type public.app_role as enum('director','administrator','accountant','teacher','parent','student'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,role public.app_role not null default 'parent',phone text,created_at timestamptz default now());
create table if not exists public.students(id uuid primary key default gen_random_uuid(),admission_no text unique not null,first_name text not null,last_name text not null,gender text check(gender in('Female','Male')),date_of_birth date,class_name text not null,parent_name text,parent_phone text,parent_email text,parent_user_id uuid references public.profiles(id),status text not null default 'Active',created_at timestamptz default now());
create table if not exists public.staff(id uuid primary key default gen_random_uuid(),employee_no text unique not null,first_name text not null,last_name text not null,role_title text not null,phone text,email text,monthly_salary numeric(12,2) default 0,status text default 'Active',created_at timestamptz default now());
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),student_id text not null,term text not null,academic_year int default 2027,fee_type text not null,amount numeric(12,2) not null check(amount>0),payment_date date default current_date,payment_method text,reference text,created_at timestamptz default now());
create table if not exists public.attendance(id uuid primary key default gen_random_uuid(),student_id text not null,attendance_date date default current_date,status text not null,remarks text,created_at timestamptz default now());
create table if not exists public.assessments(id uuid primary key default gen_random_uuid(),student_id text not null,term text not null,academic_year int default 2027,subject text not null,assessment_name text,score numeric not null check(score>=0),max_score numeric not null check(max_score>0 and score<=max_score),teacher_comment text,created_at timestamptz default now());
create table if not exists public.expenses(id uuid primary key default gen_random_uuid(),expense_date date default current_date,category text not null,description text not null,amount numeric(12,2) not null check(amount>0),paid_to text,reference text,created_at timestamptz default now());
create table if not exists public.notices(id uuid primary key default gen_random_uuid(),title text not null,message text not null,audience text not null,publish_date date default current_date,status text default 'Draft',created_at timestamptz default now());
create or replace function public.my_role() returns public.app_role language sql stable security definer set search_path=public as $$select role from public.profiles where id=auth.uid()$$;
create or replace function public.is_management() returns boolean language sql stable security definer set search_path=public as $$select coalesce(public.my_role() in('director','administrator'),false)$$;
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$select coalesce(public.my_role() in('director','administrator','accountant','teacher'),false)$$;
do $$ declare t text; begin foreach t in array array['profiles','students','staff','payments','attendance','assessments','expenses','notices'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy "profiles own or management" on public.profiles for select to authenticated using(id=auth.uid() or public.is_management());
create policy "profiles management edit" on public.profiles for all to authenticated using(public.is_management()) with check(public.is_management());
create policy "students staff or linked parent" on public.students for select to authenticated using(public.is_staff() or parent_user_id=auth.uid());
create policy "students management" on public.students for all to authenticated using(public.is_management()) with check(public.is_management());
create policy "staff management finance read" on public.staff for select to authenticated using(public.my_role() in('director','administrator','accountant'));
create policy "staff management edit" on public.staff for all to authenticated using(public.is_management()) with check(public.is_management());
create policy "payments read finance" on public.payments for select to authenticated using(public.my_role() in('director','administrator','accountant'));
create policy "payments add finance" on public.payments for insert to authenticated with check(public.my_role() in('director','administrator','accountant'));
create policy "attendance read staff" on public.attendance for select to authenticated using(public.is_staff());
create policy "attendance add teaching staff" on public.attendance for insert to authenticated with check(public.my_role() in('director','administrator','teacher'));
create policy "assessments read staff" on public.assessments for select to authenticated using(public.is_staff());
create policy "assessments add teaching staff" on public.assessments for insert to authenticated with check(public.my_role() in('director','administrator','teacher'));
create policy "expenses finance read" on public.expenses for select to authenticated using(public.my_role() in('director','administrator','accountant'));
create policy "expenses finance add" on public.expenses for insert to authenticated with check(public.my_role() in('director','administrator','accountant'));
create policy "notices read published" on public.notices for select to authenticated using(status='Published' or public.my_role() in('director','administrator','teacher'));
create policy "notices staff manage" on public.notices for all to authenticated using(public.my_role() in('director','administrator','teacher')) with check(public.my_role() in('director','administrator','teacher'));
